{"implementation": "def solve(case):
    threshold = case.get('threshold')
    if threshold is None:
        raise ValueError("Missing threshold")
    calls = case.get('calls')
    if calls is None:
        raise ValueError("Missing calls")
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")
    accepted_ids = []
    diagnostics = []
    for call in calls:
        if not isinstance(call, dict):
            raise ValueError("call must be an object")
        call_id = call.get('call_id')
        loss_without = call.get('loss_without_call')
        loss_with = call.get('loss_with_call')
        pred_tokens = call.get('prediction_tokens')
        parseable = call.get('parseable')
        if any(x is None for x in (call_id, loss_without, loss_with, pred_tokens, parseable)):
            raise ValueError("Missing field in call")
        gain = loss_without - loss_with
        normalized_gain = gain / max(pred_tokens, 1)
        accepted = bool(parseable) and normalized_gain >= threshold
        if accepted:
            accepted_ids.append(call_id)
        diagnostics.append({
            'accepted': accepted,
            'call_id': call_id,
            'normalized_gain': normalized_gain
        })
    return {
        'accepted_call_ids': accepted_ids,
        'diagnostics': diagnostics
    }"}
